5	use App\Models\Core\Site\Site;
6	use App\Models\Core\Site\SiteMedia;
7	use App\Services\Professional\SectionVisibilityService;
8	use Illuminate\Support\Facades\Log;
9	
10	// V2: Re-evaluates section visibility when media rows are saved, deleted, or restored.
11	// Currently handles gallery images and documents — each maps to a distinct section
12	// block type; mapping is defined in poolToBlockType().
13	class SiteMediaObserver
14	{
15	    public bool $afterCommit = true;
16	
17	    public function __construct(
18	        private readonly SectionVisibilityService $visibilityService,
19	    ) {}
20	
21	    public function saved(SiteMedia $media): void
22	    {
23	        $this->reevaluateIfRelevant($media);
24	    }
25	
26	    public function deleted(SiteMedia $media): void
27	    {
28	        $this->reevaluateIfRelevant($media);
29	    }
30	
31	    public function restored(SiteMedia $media): void
32	    {
33	        $this->reevaluateIfRelevant($media);
34	    }
35	
36	    private function reevaluateIfRelevant(SiteMedia $media): void
37	    {
38	        $blockType = $this->poolToBlockType($media->pool);
39	        if ($blockType === null) {
40	            return;
41	        }
42	
43	        try {
44	            $site = Site::query()->find($media->site_id);
45	            if (! $site || ! $site->professional_id) {
46	                return;
47	            }
48	
49	            $this->visibilityService->reevaluateEnabled(
50	                (string) $site->professional_id,
51	                (string) $media->site_id,
52	                $blockType
53	            );
54	        } catch (\Throwable $e) {
55	            Log::warning('Section visibility reevaluation failed on SiteMedia event', [
56	                'site_media_id' => $media->id,
57	                'site_id' => $media->site_id,
58	                'pool' => $media->pool,
59	                'block_type' => $blockType,
60	                'message' => $e->getMessage(),
61	            ]);
62	        }
63	    }
64	
65	    /**
66	     * Map a site_media pool to the section block_type it feeds. Returns null
67	     * for pools that don't drive a section (brand gallery, design, product).
68	     */
69	    private function poolToBlockType(?string $pool): ?string
70	    {
71	        return match ($pool) {
72	            SiteMedia::POOL_GALLERY => 'gallery',
73	            SiteMedia::POOL_DOCUMENTS => 'documents',
74	            default => null,
75	        };
76	    }
77	}
