10	// V2: Invalidates site cache and dispatches cache warm job on publish.
11	class SiteObserver
12	{
13	    public bool $afterCommit = true;
14	
15	    public function __construct(
16	        private readonly SiteCacheService $siteCache,
17	    ) {}
18	
19	    public function saved(Site $site): void
20	    {
21	        try {
22	            $this->siteCache->invalidateSite($site);
23	        } catch (\Throwable $e) {
24	            Log::warning('Site cache invalidation failed on save', [
25	                'site_id' => $site->id,
26	                'subdomain' => $site->subdomain,
27	                'message' => $e->getMessage(),
28	            ]);
29	        }
30	
31	        // Warm cache asynchronously if published
32	        if ($site->is_published) {
33	            try {
34	                WarmPublicSiteCacheJob::dispatch(strtolower($site->subdomain))->afterCommit();
35	            } catch (\Throwable $e) {
36	                // Never fail the write path because cache warming failed.
37	                Log::warning('WarmPublicSiteCacheJob dispatch failed', [
38	                    'site_id' => $site->id,
39	                    'subdomain' => $site->subdomain,
40	                    'message' => $e->getMessage(),
41	                ]);
42	            }
43	        }
44	    }
45	
46	    public function deleted(Site $site): void
47	    {
48	        try {
49	            $this->siteCache->invalidateSite($site);
50	        } catch (\Throwable $e) {
51	            Log::warning('Site cache invalidation failed on delete', [
52	                'site_id' => $site->id,
53	                'subdomain' => $site->subdomain,
54	                'message' => $e->getMessage(),
55	            ]);
56	        }
57	    }
58	}
